def move_structured_details_into_body(apps, schema_editor):
    translation_model = apps.get_model("content", "WorkshopTranslation")
    labels = {
        "vi": {
            "heading": "Thông tin bổ sung",
            "location": "Địa điểm",
            "address": "Địa chỉ",
            "map": "Bản đồ",
            "instructor": "Người hướng dẫn",
            "fee": "Chi phí",
        },
        "en": {
            "heading": "Additional information",
            "location": "Location",
            "address": "Address",
            "map": "Map",
            "instructor": "Facilitator",
            "fee": "Fee",
        },
    }
    for translation in translation_model.objects.all().iterator():
        copy = labels.get(translation.locale, labels["en"])
        details = []
        if translation.location_name.strip():
            details.append((copy["location"], translation.location_name.strip(), None))
        if translation.address.strip():
            details.append((copy["address"], " ".join(translation.address.split()), None))
        if translation.map_url.strip():
            map_url = translation.map_url.strip()
            if map_url.startswith("http://"):
                map_url = f"https://{map_url.removeprefix('http://')}"
            details.append((copy["map"], map_url, map_url))
        instructor = " — ".join(
            value.strip()
            for value in (translation.instructor_name, translation.instructor_role)
            if value.strip()
        )
        if instructor:
            details.append((copy["instructor"], instructor, None))
        if translation.fee_text.strip():
            details.append((copy["fee"], translation.fee_text.strip(), None))
        if not details:
            continue

        body = translation.body if isinstance(translation.body, dict) else {}
        content = body.get("content")
        if not isinstance(content, list):
            content = []
        content = [
            *content,
            {
                "type": "heading",
                "attrs": {"level": 2},
                "content": [{"type": "text", "text": copy["heading"]}],
            },
        ]
        for label, value, link in details:
            value_node = {"type": "text", "text": value}
            if link:
                value_node["marks"] = [{"type": "link", "attrs": {"href": link}}]
            content.append(
                {
                    "type": "paragraph",
                    "content": [
                        {"type": "text", "text": f"{label}: "},
                        value_node,
                    ],
                }
            )
        translation.body = {**body, "type": "doc", "content": content}
        translation.save(update_fields=["body"])


